CREATE COLUMN TABLE "TEST_AP"."OBTL" ("AbsEntry" INTEGER CS_INT NOT NULL , "MessageID" INTEGER CS_INT, "BinAbs" INTEGER CS_INT, "SnBMDAbs" INTEGER CS_INT DEFAULT -1, "Quantity" DECIMAL(21,6) CS_FIXED, "ITLEntry" INTEGER CS_INT DEFAULT -1, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OBTL_MESSAGE_ID" ON "TEST_AP"."OBTL" ( "MessageID" ASC );
CREATE INDEX "OBTL_BIN_ABS" ON "TEST_AP"."OBTL" ( "BinAbs" ASC )